def choose_move(observation):
    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            try:
                return int(value[0]), int(value[1])
            except Exception:
                return default
        return default

    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, opp_p)
            if best is None or d > best:
                best = d
                target = c
        return step_toward(self_p, target if target is not None else self_p)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        target = None
        for t in targets:
            tp = pos(t, self_p)
            score = manhattan(self_p, tp) * 2 - manhattan(opp_p, tp)
            if best is None or score < best or (score == best and manhattan(self_p, tp) < manhattan(self_p, target)):
                best = score
                target = tp
        if target is not None:
            return step_toward(self_p, target)
        center = (gw // 2, gh // 2) if gw and gh else opp_p
        return step_toward(self_p, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    target = None
    for r in resources:
        rp = pos(r, self_p)
        score = manhattan(self_p, rp) * 2 - manhattan(opp_p, rp)
        if best is None or score < best or (score == best and manhattan(self_p, rp) < manhattan(self_p, target)):
            best = score
            target = rp
    if target is not None:
        return step_toward(self_p, target)

    center = (gw // 2, gh // 2) if gw and gh else opp_p
    if gw and gh:
        return step_toward(self_p, center)
    return step_toward(self_p, opp_p)

